import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./FloodMap.css";
import L from 'leaflet';
import kaladyRiver from "../assets/kalady-river.png";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const ITEMS_PER_PAGE = 10;

// --- RESPONSIVE CSS OVERRIDES ---
const responsiveStyles = `
  .rd-advanced-page { width: 100%; overflow-x: hidden; }
  .rd-content-container { padding: 0 20px; max-width: 1200px; margin: 0 auto; }
  
  @media (max-width: 768px) {
    .hero-main-title { font-size: 2rem !important; }
    .hero-sub-text { font-size: 0.9rem !important; padding: 0 15px; }
    .rd-status-card-top { width: 85% !important; flex-direction: column; text-align: center; }
    .rd-split-layout { grid-template-columns: 1fr !important; display: flex; flex-direction: column; }
    .rd-hero-fullscreen { min-height: 50vh !important; }
    .hero-content-wrapper { padding-top: 60px; }
    .map-controls-container { left: 10px !important; top: 70px !important; flex-direction: column; }
    .search-input { width: 150px !important; }
    .floating-alert { width: 95% !important; top: 5px !important; }
  }

  /* Fix for the Dashboard/Logo overlap seen in image */
  .header-nav-overlay {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px 20px;
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1100;
    background: linear-gradient(to bottom, rgba(0,0,0,0.5), transparent);
  }
`;

// 🎨 HELPER: Risk Color Logic
const getRiskStatus = (depth, isNormalState) => {
  if (isNormalState) {
    return {
      color: "#10b981", 
      bg: "rgba(16, 185, 129, 0.1)",
      label: "Safe / Normal Flow",
      icon: "fa-check-circle",
      shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)"
    };
  }
  if (depth <= 3) return { color: "#10b981", bg: "rgba(16, 185, 129, 0.1)", label: "Low Risk", icon: "fa-check-circle", shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)" };
  if (depth < 8) return { color: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)", label: "Moderate Risk", icon: "fa-exclamation-circle", shadow: "0 4px 14px 0 rgba(245, 158, 11, 0.39)" };
  return { color: "#ef4444", bg: "rgba(239, 68, 68, 0.1)", label: "Critical Risk", icon: "fa-exclamation-triangle", shadow: "0 4px 14px 0 rgba(239, 68, 68, 0.39)" };
};

const generateSmartName = (osmData) => {
  if (!osmData) return "Unknown Location";
  const addr = osmData.address || {};
  const street = addr.road || addr.street || addr.pedestrian || addr.path || addr.lane;
  const area = addr.neighbourhood || addr.suburb || addr.residential || addr.village;
  const town = addr.town || addr.city || addr.county;
  if (street && area) return `${street}, ${area}`;
  if (street && town) return `${street}, ${town}`;
  if (area && town) return `${area}, ${town}`;
  if (osmData.display_name) return osmData.display_name.split(", ").slice(0, 2).join(", ");
  return town || "Flood Point";
};

const LocationPopup = ({ lat, lon, depth, isNormalState }) => {
  const [address, setAddress] = useState("Loading details...");
  const [title, setTitle] = useState("Location Details");
  const status = getRiskStatus(depth, isNormalState);

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        if (res.data) {
          setTitle(generateSmartName(res.data));
          setAddress(res.data.display_name);
        }
      } catch (err) { setAddress("Address unavailable"); }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div style={{ fontFamily: 'Inter, sans-serif', minWidth: '200px', padding: '5px' }}>
      <div style={{ color: status.color, fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', marginBottom: '4px' }}>{status.label}</div>
      <strong style={{ fontSize: '14px', color: '#0f172a', display: 'block', marginBottom: '8px' }}>{title}</strong>
      {!isNormalState && (
        <div style={{ background: '#f8fafc', padding: '8px', borderRadius: '6px', marginBottom: '8px' }}>
          <span style={{ color: '#64748b', fontSize: '11px' }}>Water Depth:</span>
          <strong style={{ color: status.color, marginLeft: '5px', fontSize: '14px' }}>{depth}m</strong>
        </div>
      )}
      <div style={{ fontSize: '10px', color: '#94a3b8', lineHeight: '1.4' }}>{address}</div>
    </div>
  );
};

const MapController = ({ targetLoc }) => {
  const map = useMap();
  useEffect(() => {
    if (targetLoc) { map.flyTo(targetLoc, 14, { animate: true, duration: 1.5 }); }
  }, [targetLoc, map]);
  return null;
};

const CustomMapControls = ({ onSearch, onFindMe }) => {
  const [query, setQuery] = useState("");
  const [searching, setSearching] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`);
      if (res.data && res.data.length > 0) {
        const { lat, lon } = res.data[0];
        onSearch([parseFloat(lat), parseFloat(lon)]);
      }
    } catch (err) { console.error(err); }
    finally { setSearching(false); }
  };

  return (
    <div className="map-controls-container" style={{ 
      position: 'absolute', top: '20px', left: '60px', zIndex: 1000, display: 'flex', gap: '10px' 
    }}>      
      <form onSubmit={handleSearch} style={{
        display: 'flex', background: 'rgba(255, 255, 255, 0.9)', backdropFilter: 'blur(12px)',
        boxShadow: '0 4px 12px rgba(0,0,0,0.15)', borderRadius: '12px', padding: '4px'
      }}>
        <input
          type="text" value={query} onChange={(e) => setQuery(e.target.value)}
          placeholder="Search..."
          className="search-input"
          style={{ padding: '8px 12px', border: 'none', outline: 'none', background: 'transparent', width: '180px' }}
        />
        <button type="submit" style={{
          background: '#3b82f6', color: 'white', border: 'none', width: '38px', height: '38px', borderRadius: '10px', cursor: 'pointer'
        }}>
          {searching ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-search"></i>}
        </button>
      </form>
      <button onClick={onFindMe} style={{
        background: 'white', color: '#3b82f6', border: 'none', width: '46px', height: '46px', borderRadius: '12px',
        boxShadow: '0 4px 12px rgba(0,0,0,0.15)', cursor: 'pointer'
      }}>
        <i className="fas fa-location-arrow"></i>
      </button>
    </div>
  );
};

const MapLegend = () => (
  <div style={{
    position: 'absolute', bottom: '20px', right: '10px', zIndex: 1000,
    background: 'rgba(15, 23, 42, 0.85)', backdropFilter: 'blur(8px)',
    padding: '12px', borderRadius: '10px', color: 'white', fontSize: '0.75rem'
  }}>
    <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}><span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#ef4444' }}></span> Critical</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}><span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#f59e0b' }}></span> Moderate</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}><span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#10b981' }}></span> Low Risk</div>
    </div>
  </div>
);

const Pagination = ({ currentPage, totalItems, onPageChange }) => {
  const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
  if (totalPages <= 1) return null;
  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '15px', margin: '20px 0' }}>
      <button onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1} style={{ padding: '8px 12px', background: '#e2e8f0', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Prev</button>
      <span style={{ fontWeight: '600' }}>{currentPage} / {totalPages}</span>
      <button onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages} style={{ padding: '8px 12px', background: '#e2e8f0', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Next</button>
    </div>
  );
};

const AffectedAreaItem = ({ data, index }) => {
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState(null);
  const [loading, setLoading] = useState(false);
  const [displayName, setDisplayName] = useState(data.place);
  const status = getRiskStatus(data.depth, false);

  const fetchDetails = async () => {
    if (details || loading) return;
    setLoading(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`);
      if (res.data) { setDetails(res.data); setDisplayName(generateSmartName(res.data)); }
    } catch (e) { setDetails({ error: true }); }
    finally { setLoading(false); }
  };

  return (
    <div style={{ background: 'white', borderRadius: '12px', marginBottom: '12px', borderLeft: `5px solid ${status.color}`, padding: '15px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' }}>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
          <div style={{ background: status.bg, color: status.color, width: '40px', height: '40px', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <i className={`fas ${status.icon}`}></i>
          </div>
          <div>
            <h4 style={{ margin: 0, fontSize: '0.95rem', color: '#1e293b' }}>{displayName}</h4>
            <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Depth: <strong>{data.depth}m</strong></span>
          </div>
        </div>
        <button onClick={() => { if (!expanded) fetchDetails(); setExpanded(!expanded); }} style={{ background: 'none', border: '1px solid #e2e8f0', padding: '5px 10px', borderRadius: '6px', cursor: 'pointer', fontSize: '0.75rem' }}>
          {expanded ? 'Hide' : 'Details'}
        </button>
      </div>
      {expanded && <div style={{ marginTop: '10px', fontSize: '0.8rem', color: '#64748b', padding: '10px', background: '#f8fafc', borderRadius: '8px' }}>{loading ? 'Loading...' : details?.display_name || 'No data'}</div>}
    </div>
  );
};

const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  const [severePage, setSeverePage] = useState(1);
  const [otherPage, setOtherPage] = useState(1);
  const [showAllAreas, setShowAllAreas] = useState(false);
  const [mapCenter, setMapCenter] = useState([10.16, 76.43]);
  const [userPos, setUserPos] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, { params: { level: simulatedLevel } });
        if (response.data) {
          if (response.data.data) response.data.data.sort((a, b) => b.depth - a.depth);
          setFloodData(response.data);
        }
      } catch (error) { console.error(error); }
      finally { setLoading(false); }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  const handleLocateUser = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((p) => {
        const c = [p.coords.latitude, p.coords.longitude];
        setUserPos(c); setMapCenter(c);
      });
    }
  };

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Syncing Satellite Data...</p></div>;

  const threshold = floodData?.current_water_level || 3.5;
  const isNormalState = threshold <= 3.0;
  const severeZones = floodData?.data?.filter(d => d.depth >= threshold) || [];
  const otherZones = floodData?.data?.filter(d => d.depth < threshold) || [];
  const currentSevere = severeZones.slice((severePage - 1) * ITEMS_PER_PAGE, severePage * ITEMS_PER_PAGE);
  
  const getAlert = (level) => {
    if (level < 3) return { title: "Conditions Normal", message: "Water levels are safe.", color: "#10b981", bg: "rgba(255, 255, 255, 0.95)", icon: "fa-check-circle" };
    if (level < 8) return { title: "Caution: Rising Water", message: "Low-lying areas may be affected.", color: "#f59e0b", bg: "rgba(255, 255, 255, 0.95)", icon: "fa-exclamation-circle" };
    return { title: "⚠️ Flood Warning", message: "Immediate precautions required.", color: "#ef4444", bg: "rgba(255, 255, 255, 0.95)", icon: "fa-exclamation-triangle" };
  };

  const alertData = getAlert(threshold);

  return (
    <div className="rd-advanced-page">
      <style>{responsiveStyles}</style>

      {/* HEADER FIX: Separated from Hero to prevent overlap */}
      <header className="header-nav-overlay">
        <div className="rd-logo" style={{ color: 'white', fontWeight: 'bold', cursor: 'pointer' }} onClick={() => navigate('/')}>
          <i className="fas fa-satellite-dish"></i> PeriyarRisk
        </div>
        <button onClick={() => navigate('/river-forecast')} style={{
          background: 'rgba(255,255,255,0.2)', border: '1px solid white', color: 'white', padding: '6px 12px', borderRadius: '8px', cursor: 'pointer', backdropFilter: 'blur(5px)'
        }}>
          Dashboard
        </button>
      </header>

      {/* 1. HERO SECTION */}
      <div className="rd-hero-fullscreen" style={{ 
          backgroundImage: `url(${kaladyRiver})`, backgroundSize: 'cover', backgroundPosition: 'center',
          minHeight: '45vh', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative'
      }}>
        <div style={{ position: 'absolute', inset: 0, background: 'rgba(15, 23, 42, 0.6)', zIndex: 1 }}></div>
        
        <div className="hero-content-wrapper" style={{ position: 'relative', zIndex: 2, textAlign: 'center', color: 'white', width: '100%' }}>
          <h1 className="hero-main-title" style={{ fontSize: '3rem', margin: '0 0 10px 0' }}>Flood Risk Analysis</h1>
          <p className="hero-sub-text" style={{ opacity: 0.9, marginBottom: '20px' }}>Live hydrological simulation for Periyar Basin.</p>
          
          <div className="rd-status-card-top" style={{ 
            background: 'rgba(255, 255, 255, 0.15)', backdropFilter: 'blur(10px)', border: '1px solid rgba(255,255,255,0.2)',
            padding: '15px 30px', borderRadius: '15px', display: 'inline-flex', alignItems: 'center', gap: '20px'
          }}>
            <i className="fas fa-water" style={{ fontSize: '2rem', color: '#60a5fa' }}></i>
            <div style={{ textAlign: 'left' }}>
              <span style={{ fontSize: '0.8rem', textTransform: 'uppercase' }}>Current Water Level</span>
              <p style={{ fontSize: '2rem', fontWeight: '800', margin: 0 }}>{threshold}m</p>
            </div>
          </div>
        </div>
      </div>

      <main className="rd-content-container" style={{ marginTop: '-40px', position: 'relative', zIndex: 5 }}>
        
        {/* 2. MAP SECTION */}
        <section style={{ height: '60vh', borderRadius: '20px', overflow: 'hidden', boxShadow: '0 10px 30px rgba(0,0,0,0.1)', position: 'relative', background: '#eee' }}>
          
          <div className="floating-alert" style={{
            position: 'absolute', top: '15px', left: '50%', transform: 'translateX(-50%)', zIndex: 1001,
            width: '80%', padding: '10px 20px', borderRadius: '12px', display: 'flex', alignItems: 'center', gap: '15px',
            background: 'white', borderLeft: `5px solid ${alertData.color}`, boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
          }}>
            <i className={`fas ${alertData.icon}`} style={{ color: alertData.color, fontSize: '1.2rem' }}></i>
            <div>
              <h4 style={{ margin: 0, fontSize: '0.9rem', color: alertData.color }}>{alertData.title}</h4>
              <p style={{ margin: 0, fontSize: '0.75rem', color: '#64748b' }}>{alertData.message}</p>
            </div>
          </div>

          <CustomMapControls onSearch={(pos) => { setMapCenter(pos); }} onFindMe={handleLocateUser} />
          <MapLegend />

          <MapContainer center={[10.16, 76.43]} zoom={13} style={{ height: "100%", width: "100%" }}>
            <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
            <MapController targetLoc={mapCenter} />
            {userPos && <CircleMarker center={userPos} radius={8} pathOptions={{ color: '#3b82f6', fillColor: '#3b82f6', fillOpacity: 0.8 }}><Popup>You are here</Popup></CircleMarker>}
            {floodData?.data?.map((point, idx) => {
              const status = getRiskStatus(point.depth, isNormalState);
              return (
                <CircleMarker key={idx} center={[point.lat, point.lon]} radius={7} pathOptions={{ color: 'white', weight: 1, fillColor: status.color, fillOpacity: 0.8 }}>
                  <Tooltip direction="top" offset={[0, -5]}><b>{point.depth}m</b></Tooltip>
                  <Popup><LocationPopup {...point} isNormalState={isNormalState} /></Popup>
                </CircleMarker>
              );
            })}
          </MapContainer>
        </section>

        {/* 3. INFO GRID */}
        <div className="rd-split-layout" style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px', marginTop: '30px' }}>
          <div className="rd-dashboard-section">
            <h3 style={{ marginBottom: '20px' }}><i className="fas fa-layer-group"></i> Affected Areas</h3>
            {isNormalState ? (
              <div style={{ textAlign: 'center', padding: '40px', background: 'white', borderRadius: '15px' }}>
                <i className="fas fa-shield-alt" style={{ fontSize: '3rem', color: '#10b981', marginBottom: '15px' }}></i>
                <h4>All Clear</h4>
                <p style={{ color: '#64748b' }}>River levels are within safe operational limits.</p>
              </div>
            ) : (
              <div>
                {currentSevere.map((item, index) => <AffectedAreaItem key={index} data={item} index={index} />)}
                <Pagination currentPage={severePage} totalItems={severeZones.length} onPageChange={setSeverePage} />
              </div>
            )}
          </div>

          <div className="rd-dashboard-section">
            <div style={{ background: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
              <h3 style={{ fontSize: '1.1rem', marginBottom: '15px' }}>System Status</h3>
              <div style={{ padding: '12px', borderLeft: `4px solid ${isNormalState ? '#10b981' : '#ef4444'}`, background: '#f8fafc', marginBottom: '15px' }}>
                <p style={{ fontSize: '0.85rem', margin: 0 }}>{isNormalState ? "Environment Stable" : "Elevated Risk Detected"}</p>
              </div>
              <p style={{ fontSize: '0.8rem', color: '#64748b' }}>
                Data source: Satellite Lidar & IoT Sensors. Updated in real-time.
              </p>
              {!isNormalState && otherZones.length > 0 && (
                <button onClick={() => setShowAllAreas(!showAllAreas)} style={{
                  width: '100%', padding: '10px', marginTop: '10px', borderRadius: '8px', border: '1px solid #3b82f6', background: 'none', color: '#3b82f6', cursor: 'pointer', fontWeight: 'bold'
                }}>
                  {showAllAreas ? 'Hide Others' : `Show ${otherZones.length} Moderate Risks`}
                </button>
              )}
            </div>
          </div>
        </div>
      </main>

      <footer style={{ background: '#0f172a', color: 'white', padding: '40px 20px', marginTop: '60px' }}>
        <div className="rd-content-container" style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '30px' }}>
          <div style={{ flex: '1', minWidth: '250px' }}>
            <h4 style={{ color: '#60a5fa' }}>Periyar Flood Watch</h4>
            <p style={{ fontSize: '0.85rem', opacity: 0.7 }}>Developed by Center for AI-IoT Innovations, ASIET Kalady.</p>
          </div>
          <div style={{ flex: '1', minWidth: '200px' }}>
            <h4>Quick Links</h4>
            <p style={{ fontSize: '0.85rem', opacity: 0.7 }}>Home | Forecast | Emergency Contacts</p>
          </div>
        </div>
        <div style={{ textAlign: 'center', marginTop: '30px', fontSize: '0.75rem', opacity: 0.5 }}>
          © {new Date().getFullYear()} Center for AI-IoT Innovations.
        </div>
      </footer>
    </div>
  );
};

export default FloodMap;
